function FontesIntegradas({termo,onAdicionar}){
 const [id,setId]=useState('am'),[q,setQ]=useState(termo||'HOSPEDAGEM'),[dados,setDados]=useState(null),[busy,setBusy]=useState(false),[erro,setErro]=useState(''),[files,setFiles]=useState({}),[notice,setNotice]=useState(''),[lastQuery,setLastQuery]=useState('');
 async function buscar(page=1){setBusy(true);setErro('');setNotice('');setFiles({});try{const d=await api(`/api/sources/${id}/search?q=${encodeURIComponent(q.trim())}&page=${page}`);setDados(d);setLastQuery(q.trim());}catch(e){setErro(e.message);setDados(null);}finally{setBusy(false);}}
 async function documentos(r){setBusy(true);setErro('');try{const u=new URL(r.url);const key=id==='mg'?u.searchParams.get('id'):id==='rs'?u.pathname.replace('/editais/',''):r.externalId;const d=await api(`/api/sources/${id}/detail?id=${encodeURIComponent(key||'')}`);setFiles(old=>({...old,[r.id]:d.files}));if(!d.files.length)setNotice('Nenhum link de documento reconhecido. Confira a publicação original.');}catch(e){setErro(e.message);}finally{setBusy(false);}}
 return <div className="platform-info">
 <div className="section-title"><h2>Cinco fontes complementares</h2><span className="demo-badge">COLETA REAL</span></div>
 <p>PNCP continua disponível na busca principal. Estas cinco fontes têm conectores de consulta nesta versão, com cobertura parcial.</p>
 <div className="summary-grid">{FONTES_V11.map(([key,nome,nota])=><article className="summary" key={key}><h4>{nome}</h4><b style={{color:'#8b6417'}}>Conector parcial · em validação</b><p>{nota}</p><button disabled={busy} className="secondary" onClick={()=>{setId(key);setDados(null);setErro('');setNotice('');}}>Selecionar fonte</button></article>)}</div>
 <div className="filters" style={{marginTop:24}}><label>Fonte<select disabled={busy} value={id} onChange={e=>{setId(e.target.value);setDados(null);setErro('');setNotice('');}}>{FONTES_V11.map(([key,nome])=><option key={key} value={key}>{nome}</option>)}</select></label><label>Palavra-chave<input disabled={busy} maxLength={160} value={q} onChange={e=>setQ(e.target.value)}/></label><button disabled={busy||!q.trim()} className="primary" onClick={()=>buscar(1)}>{busy?'Consultando…':'Buscar nesta fonte'}</button></div>
 <p className="notice">Nenhuma licitação é gerada como exemplo. Sem confirmação do prazo, o resultado aparece como “Prazo não confirmado”. Abertura da sessão não é tratada como prazo de proposta. MG e RJ podem levar mais tempo por consultarem arquivos oficiais maiores.</p>
 {erro&&<p role="alert" className="warning">{erro} Nenhum resultado fictício foi inserido. Tente novamente ou confira o portal original.</p>}
 {notice&&<p role="status" className="notice">{notice}</p>}
 {dados&&<><p><b>{dados.total} resultados para {lastQuery}</b> · Página {dados.page} de {dados.totalPages||0}<br/><small>Coleta: {new Date(dados.collectedAt).toLocaleString('pt-BR')} · {dados.source.note}</small></p>
 <div style={{display:'flex',gap:10,marginBottom:20}}><button className="secondary" disabled={busy||dados.page<=1||q.trim()!==lastQuery} onClick={()=>buscar(dados.page-1)}>Anterior</button><button className="secondary" disabled={busy||dados.page>=dados.totalPages||q.trim()!==lastQuery} onClick={()=>buscar(dados.page+1)}>Próxima</button></div>
 {!dados.rows.length&&<p>Nenhum resultado para esta palavra-chave no conjunto consultado. Isso não comprova ausência em todo o portal.</p>}
 <div className="grid">{dados.rows.map(r=><article className="summary" key={r.id}><small>{r.source} · {r.externalId}</small><h3>{r.title}</h3><p>{r.agency||'Órgão não informado'} · {r.modality||'Modalidade não informada'}</p><b>{r.value? r.value.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'Valor não informado'}</b><p>Prazo de proposta: {r.deadline?new Date(r.deadline).toLocaleString('pt-BR'):'Não confirmado'}<br/>Sessão/abertura: {r.opening?new Date(r.opening).toLocaleString('pt-BR'):'Não informado'}</p><p className="warning" style={{padding:10}}>{r.deadlineState}<br/>Situação na fonte: {r.status||'Não informada'}</p>
 <a href={r.url} target="_blank" rel="noopener noreferrer">{r.direct?'Abrir publicação original ↗':'Abrir consulta da fonte ↗'}</a>{!r.direct&&<p><small>A fonte não forneceu link individual nesta integração. Procure pelo identificador acima.</small></p>}
 {r.participation&&<p><a href={r.participation} target="_blank" rel="noopener noreferrer">Plataforma de participação ↗</a></p>}
 <div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:14}}>{['am','mg','rs'].includes(id)&&r.direct&&<button className="secondary" disabled={busy} onClick={()=>documentos(r)}>Consultar documentos</button>}<button className="primary" disabled={!onAdicionar||busy} onClick={()=>{onAdicionar({...r,query:lastQuery,files:files[r.id]||r.files});setNotice('Edital adicionado em 1. Encontrados. Confira prazo e exigências na fonte antes de decidir.');}}>Adicionar ao funil</button></div>
 {(files[r.id]||r.files).map((f,i)=><p key={f.url+i}><a href={f.url} target="_blank" rel="noopener noreferrer">{f.name} ↗</a></p>)}
 <small>Links externos; os documentos não foram copiados para o navegador nem resumidos por IA.</small>
 </article>)}</div></>}
 </div>;
}
function ResumoItens({licitacao,onSalvar}){
 const [dados,setDados]=useState(licitacao.itensPNCP||null),[busy,setBusy]=useState(false),[erro,setErro]=useState('');
 const seq=useRef(0);
 const identificador=licitacao.fonte==='PNCP'?String(licitacao.urlPNCP||'').match(/\/app\/editais\/(\d{14})\/(\d{4})\/(\d+)(?:$|[?#])/):null;
 const pagina=dados?.pagina||1,rows=dados?.paginas?.[pagina]||[];
 async function buscar(p=1,atualizar=false){
  if(!identificador)return;
  if(!atualizar&&dados?.paginas?.[p]){const n={...dados,pagina:p};setDados(n);onSalvar(n);return;}
  const request=++seq.current;setBusy(true);setErro('');
  try{
   const [,cnpj,ano,numero]=identificador;
   const r=await consultar(`${PNCP}/api/pncp/v1/orgaos/${cnpj}/compras/${ano}/${numero}/itens?pagina=${p}&tamanhoPagina=20`);
   if(!Array.isArray(r)||r.some(i=>typeof i.descricao!=='string'||i.numeroItem==null))throw Error('Formato de itens não reconhecido.');
   if(request!==seq.current)return;
   const n={paginas:{...(atualizar?{}:dados?.paginas||{}),[p]:r},pagina:p,consultadoEm:new Date().toISOString()};setDados(n);onSalvar(n);
  }catch(e){if(request===seq.current)setErro(e.message+' Confira os itens no portal original.');}
  finally{if(request===seq.current)setBusy(false);}
 }
 useEffect(()=>{if(identificador&&!licitacao.itensPNCP)buscar(1);return()=>{seq.current++;};},[licitacao.id]);
 const money=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'Não informado';
 const todosComValor=rows.length>0&&rows.every(i=>i.orcamentoSigiloso!==true&&typeof i.valorTotal==='number'&&Number.isFinite(i.valorTotal));
 return <section className="archive" style={{marginTop:24}}>
 <div className="section-title"><h3>Resumo dos itens</h3><span className="demo-badge">ITENS OFICIAIS</span></div>
 {!identificador?<p>A consulta automática de itens está disponível para registros do PNCP. Nesta fonte, confira a relação no edital e nos anexos.</p>:<>
 <p>Descrição, quantidade e valores publicados no PNCP. A tabela não substitui as especificações e condições do edital.</p>
 <button className="secondary" disabled={busy} onClick={()=>buscar(1,true)}>{busy?'Consultando itens…':'Atualizar itens oficiais'}</button>
 {erro&&<p className="warning" role="alert">{erro} Se aparecer “Rota não permitida”, atualize server/pncp.mjs com o arquivo da V14 e reinicie o servidor.</p>}
 {dados&&<><p><b>{rows.length} itens nesta página · Página {pagina}</b><br/>Total estimado dos itens desta página: {todosComValor?money(rows.reduce((sum,i)=>sum+i.valorTotal,0)):'Não calculado: valores ausentes, sigilosos ou página vazia'}<br/><small>Última consulta: {new Date(dados.consultadoEm).toLocaleString('pt-BR')}</small></p>
 {rows.length?<div style={{overflowX:'auto',background:'white',borderRadius:8}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:12,minWidth:650}}><thead><tr>{['Item','Descrição','Quantidade','Unidade','Valor unitário estimado','Valor total estimado'].map(t=><th key={t} style={{padding:12,textAlign:'left',background:'#eaf0f8',borderBottom:'1px solid #dce3ed'}}>{t}</th>)}</tr></thead><tbody>{rows.map(i=><tr key={i.numeroItem}><td style={{padding:12,verticalAlign:'top',borderBottom:'1px solid #e6ecf3'}}>{i.numeroItem}</td><td style={{padding:12,verticalAlign:'top',borderBottom:'1px solid #e6ecf3',minWidth:230}}>{i.descricao}</td><td style={{padding:12,verticalAlign:'top',borderBottom:'1px solid #e6ecf3'}}>{typeof i.quantidade==='number'?i.quantidade.toLocaleString('pt-BR'):'Não informada'}</td><td style={{padding:12,verticalAlign:'top',borderBottom:'1px solid #e6ecf3'}}>{i.unidadeMedida||'Não informada'}</td><td style={{padding:12,verticalAlign:'top',borderBottom:'1px solid #e6ecf3'}}>{i.orcamentoSigiloso===true?'Orçamento sigiloso':money(i.valorUnitarioEstimado)}</td><td style={{padding:12,verticalAlign:'top',borderBottom:'1px solid #e6ecf3'}}>{i.orcamentoSigiloso===true?'Orçamento sigiloso':money(i.valorTotal)}</td></tr>)}</tbody></table></div>:<p>O PNCP não retornou itens nesta página.</p>}
 <div style={{display:'flex',gap:10,marginTop:14}}><button className="secondary" disabled={busy||pagina<=1} onClick={()=>buscar(pagina-1)}>Itens anteriores</button><button className="secondary" disabled={busy||rows.length<20} onClick={()=>buscar(pagina+1)}>Próximos itens</button></div><small>Até 20 itens por página. O subtotal corresponde somente à página exibida; não é o valor total da contratação.</small></>}
 </>}
 <p><a href={licitacao.urlPNCP} target="_blank" rel="noopener noreferrer">Conferir itens na fonte ↗</a></p>
 </section>;
}

