function SharedWorkspace({user,onSair}){
 const [tab,setTab]=useState('Dashboard'),[list,setList]=useState([]),[team,setTeam]=useState([]),[detail,setDetail]=useState(null),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[filters,setFilters]=useState(false),[q,setQ]=useState('HOSPEDAGEM'),[uf,setUf]=useState(''),[source,setSource]=useState(''),[modality,setModality]=useState(''),[stage,setStage]=useState(''),[newTitle,setNewTitle]=useState(''),[newSource,setNewSource]=useState(''),[comment,setComment]=useState(''),[audit,setAudit]=useState([]),[actor,setActor]=useState(''),[auditPage,setAuditPage]=useState(1),[manual,setManual]=useState({}),[selectedDocs,setSelectedDocs]=useState([]),[remotePage,setRemotePage]=useState(1),[remoteTotal,setRemoteTotal]=useState(null);
 const can=p=>user.admin||user.permissoes.includes(p);
 async function refresh(){const [l,t]=await Promise.all([api('/api/work/tenders'),api('/api/work/team')]);setList(l);setTeam(t);}
 useEffect(()=>{refresh().catch(e=>setMessage(e.message));},[]);
 useEffect(()=>{if(tab==='Auditoria')api('/api/work/audit?actor='+encodeURIComponent(actor)+'&page='+auditPage).then(setAudit).catch(e=>setMessage(e.message));},[tab,actor,auditPage]);
 async function run(fn){setBusy(true);setMessage('');try{await fn();}catch(e){setMessage(e.message);}finally{setBusy(false);}}
 async function open(id){await run(async()=>{const d=await api('/api/work/tenders/'+encodeURIComponent(id));setDetail(d);setManual(d.manual||{});setSelectedDocs(d.proposalDocuments||[]);});}
 async function update(changes){await run(async()=>{await api('/api/work/tenders/'+encodeURIComponent(detail.id),'PATCH',{version:detail.version,changes});const d=await api('/api/work/tenders/'+encodeURIComponent(detail.id));setDetail(d);setManual(d.manual||{});await refresh();setMessage('Alteração salva no servidor e registrada na auditoria.');});}
 async function add(input){const d=await api('/api/work/tenders','POST',input);await refresh();return d;}
 async function search(page=1){await run(async()=>{if(!can('Buscar editais'))throw Error('Sem permissão para buscar.');if(!q.trim())throw Error('Informe a palavra-chave.');const data=await api('/api/pncp-proxy/api/search/?q='+encodeURIComponent(q.trim())+'&pagina='+page);if(!Array.isArray(data.items))throw Error('Resposta de busca inválida.');setRemotePage(page);setRemoteTotal(data.total);let count=0,failed=0;for(const x of data.items){try{const d=await api(`/api/pncp-proxy/api/consulta/v1/orgaos/${x.orgao_cnpj}/compras/${x.ano}/${x.numero_sequencial}`);const end=instante(d.dataEncerramentoProposta);if(d.situacaoCompraId!==1||!Number.isFinite(end)||end<=Date.now())continue;await add({id:d.numeroControlePNCP,titulo:d.objetoCompra||x.description,orgao:d.orgaoEntidade?.razaoSocial||'',fonte:'PNCP',uf:d.unidadeOrgao?.ufSigla||'',modalidade:d.modalidadeNome||'',valor:d.orcamentoSigilosoCodigo!==1?'Orçamento sigiloso':d.valorTotalEstimado>0?d.valorTotalEstimado.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'',prazo:dataBR(d.dataEncerramentoProposta),oficial:d,coletadoEm:new Date().toISOString(),palavraBusca:q.trim(),urlPNCP:`https://pncp.gov.br/app/editais/${x.orgao_cnpj}/${x.ano}/${x.numero_sequencial}`,urlOrigem:d.linkSistemaOrigem||''});count++;}catch{failed++;}}setMessage(`${count} oportunidades com prazo futuro adicionadas. ${failed} detalhes falharam. Nenhum resultado foi inventado.`);setTab('Editais encontrados');});}
 const visible=list.filter(e=>(!uf||e.uf===uf)&&(!source||e.fonte===source)&&(!modality||e.modalidade===modality)&&(!stage||String(e.etapa)===stage));
 const nearby=visible.filter(e=>{const n=instante(e.oficial?.dataEncerramentoProposta)-Date.now();return n>0&&n<=7*86400000;}).sort((a,b)=>instante(a.oficial?.dataEncerramentoProposta)-instante(b.oficial?.dataEncerramentoProposta));
 const manualKeys=['Contratante','Identificação','Modalidade e julgamento','Datas e prazos','Itens e quantidades','Valores','Habilitação jurídica e fiscal','Capacidade técnica','Qualificação financeira','Condições de execução','Pagamento','Garantia','Penalidades','Documentos da proposta','Riscos e inconsistências'];
 return <div className="er-preview"><style>{CSS+VISUAL_V18+`.shared-toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:18px 0}.shared-toolbar input,.shared-toolbar select{padding:12px;border:1px solid #d8e3f0;border-radius:8px}.shared-modal input,.shared-modal select,.shared-modal textarea{padding:10px;border:1px solid #d8e3f0;border-radius:7px;width:100%;margin:5px 0}.shared-modal textarea{min-height:75px}.shared-modal input[type=checkbox]{width:auto}.shared-modal label{display:block;margin:10px 0}.audit-detail{white-space:pre-wrap;word-break:break-word;font-size:11px}.summary-evidence{background:#f5f8fd;padding:12px;border-radius:8px;font-size:12px}.shared-modal h3{margin-top:26px}.server-badge{font-size:12px;color:#5a7290}`}</style><aside className="sidebar"><div className="brand" style={{display:'block',padding:14,background:'white',borderRadius:12}}><img src={LOGO_MARACANAS} alt="Maracanãs" style={{width:'100%'}}/></div>{['Dashboard','Funil de editais','Editais encontrados','Decisões','Plataformas','Importar edital',...(user.admin?['Administração','Auditoria']:[]),'Acesso à conta'].map(t=><button key={t} className={'nav '+(tab===t?'active':'')} onClick={()=>{setTab(t);setMessage('');}}>{t}</button>)}<button className="nav" onClick={onSair}>Sair</button></aside><main><header><span>Central de licitações / <b>{tab}</b></span><span>{user.nome}</span></header><section className="workspace"><div className="heading"><div><h1>{tab}</h1><p>Oportunidades, documentos e decisões compartilhados.</p></div><button className="secondary" disabled={busy} onClick={()=>run(refresh)}>Atualizar acervo</button></div><p className="server-badge">Dados no servidor · cada ação usa seu login · {list.length} licitações carregadas (limite 2.000)</p>{message&&<div className="warning" role="status">{message}</div>}
{['Dashboard','Funil de editais','Editais encontrados','Decisões'].includes(tab)&&<><div className="reference-stats">{[['Encontrados',visible.length],['Em análise',visible.filter(e=>e.etapa===1).length],['Aprovados',visible.filter(e=>e.decisao==='Participar').length],['Prazos próximos',nearby.length]].map(([name,n])=><div key={name}><div><small>{name}</small><strong>{n}</strong></div></div>)}</div><div className="shared-toolbar"><input aria-label="Palavra-chave PNCP" value={q} onChange={e=>{setQ(e.target.value);setRemoteTotal(null);}}/><button className="primary" disabled={busy||!can('Buscar editais')} onClick={()=>search(1)}>{busy?'Aguarde…':'Buscar no PNCP'}</button><button className="secondary" aria-expanded={filters} onClick={()=>setFilters(v=>!v)}>{filters?'Ocultar filtros':'Mostrar filtros'}</button></div>{remoteTotal!==null&&<p>PNCP: página {remotePage} de {Math.ceil(remoteTotal/20)} · {remoteTotal} resultados antes de conferir os detalhes <button disabled={busy||remotePage<=1} onClick={()=>search(remotePage-1)}>Anterior</button> <button disabled={busy||remotePage*20>=remoteTotal} onClick={()=>search(remotePage+1)}>Próxima</button></p>}{filters&&<div className="shared-toolbar"><label>Estado<select value={uf} onChange={e=>setUf(e.target.value)}><option value="">Todos</option>{UFS.map(v=><option key={v}>{v}</option>)}</select></label><label>Fonte<select value={source} onChange={e=>setSource(e.target.value)}><option value="">Todas</option>{[...new Set(list.map(e=>e.fonte).filter(Boolean))].map(v=><option key={v}>{v}</option>)}</select></label><label>Modalidade<select value={modality} onChange={e=>setModality(e.target.value)}><option value="">Todas</option>{[...new Set(list.map(e=>e.modalidade).filter(Boolean))].map(v=><option key={v}>{v}</option>)}</select></label><label>Etapa<select value={stage} onChange={e=>setStage(e.target.value)}><option value="">Todas</option>{ETAPAS.map((v,i)=><option key={v} value={i}>{v}</option>)}</select></label><button onClick={()=>{setUf('');setSource('');setModality('');setStage('');}}>Limpar</button><small>Filtros sobre o acervo salvo; busca remota PNCP por palavra-chave e propostas abertas.</small></div>}<div className="filter-chips">{[[uf,()=>setUf('')],[source,()=>setSource('')],[modality,()=>setModality('')],[stage?ETAPAS[Number(stage)]:'',()=>setStage('')]].filter(([v])=>v).map(([v,f])=><button key={v} onClick={f}>{v} ×</button>)}</div>
<div className="opportunity-layout"><section className="opportunity-table"><h2>{tab==='Dashboard'?'Oportunidades do acervo':'Licitações'}</h2><div className="table-scroll"><table><thead><tr><th>Edital / órgão</th><th>Local</th><th>Prazo</th><th>Iniciada por</th><th>Etapa</th></tr></thead><tbody>{visible.filter(e=>tab!=='Decisões'||e.decisao).map(e=><tr key={e.id}><td><button className="edital-link" disabled={busy} onClick={()=>open(e.id)}>{e.titulo}</button><small>{e.orgao||'Órgão não informado'} · {e.fonte||'Origem não informada'}</small></td><td>{e.uf||'Não informado'}</td><td>{e.prazo||'Não confirmado'}</td><td>{e.creatorName}<small>{new Date(e.createdAt).toLocaleString('pt-BR')}</small></td><td>{ETAPAS[e.etapa]}</td></tr>)}</tbody></table></div>{!visible.length&&<p className="dash-empty">Nenhuma licitação nesta seleção.</p>}</section><aside className="deadline-aside"><section className="deadline-box"><h3>Atenção aos prazos</h3><p>Próximos 7 dias</p>{nearby.slice(0,6).map(e=><button key={e.id} onClick={()=>open(e.id)}><b>{e.titulo}</b><small>{e.prazo}</small></button>)}{!nearby.length&&<p>Nenhum prazo próximo confirmado.</p>}</section></aside></div></>}
{tab==='Importar edital'&&<section className="platform-info"><h2>Iniciar uma licitação por PDF</h2><p>Crie a ficha e anexe o edital e seus anexos. Dados ausentes ficam em branco; não há preenchimento automático por suposição.</p><form onSubmit={e=>{e.preventDefault();run(async()=>{const d=await add({titulo:newTitle.trim(),fonte:newSource.trim()});setNewTitle('');const full=await api('/api/work/tenders/'+encodeURIComponent(d.id));setDetail(full);setManual({});setSelectedDocs([]);});}}><label>Título da ficha<input required value={newTitle} onChange={e=>setNewTitle(e.target.value)} maxLength={8000}/></label><label>Origem informada pela equipe<input value={newSource} onChange={e=>setNewSource(e.target.value)} placeholder="Ex.: Sebrae"/></label><button disabled={busy||!can('Buscar editais')} className="primary">Criar ficha e anexar PDFs</button></form></section>}
{tab==='Plataformas'&&<FontesIntegradas termo={q} onAdicionar={can('Buscar editais')?r=>run(async()=>{await add({id:r.id,titulo:r.title,orgao:r.agency||'',fonte:r.source,uf:({am:'AM',mg:'MG',rs:'RS',sesc:'BA',rj:'RJ'})[r.sourceId]||'',modalidade:r.modality||'',valor:r.value?r.value.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'',prazo:r.deadline?new Date(r.deadline).toLocaleString('pt-BR'):'',oficial:{dataEncerramentoProposta:r.deadline||null,situacaoCompraNome:r.status||''},urlOrigem:r.url,coletadoEm:r.collectedAt});setMessage('Oportunidade adicionada ao acervo compartilhado.');}):undefined}/>}
{tab==='Administração'&&user.admin&&<ServerAdmin/>}{tab==='Acesso à conta'&&<MinhaConta/>}
{tab==='Auditoria'&&user.admin&&<section className="platform-info"><h2>Histórico por colaborador</h2><div className="shared-toolbar"><select value={actor} onChange={e=>{setActor(e.target.value);setAuditPage(1);}}><option value="">Todos</option>{team.map(t=><option key={t.id} value={t.id}>{t.nome}</option>)}</select><button onClick={()=>run(async()=>setAudit(await api('/api/work/audit?actor='+encodeURIComponent(actor)+'&page='+auditPage)))}>Atualizar histórico</button><button disabled={auditPage<=1} onClick={()=>setAuditPage(p=>p-1)}>Anterior</button><span>Página {auditPage}</span><button disabled={audit.length<100} onClick={()=>setAuditPage(p=>p+1)}>Próxima</button></div>{audit.map(a=><details key={a.id}><summary>{new Date(a.time).toLocaleString('pt-BR')} · {a.name} · {a.action} {a.tender_id?'· '+a.tender_id:''}</summary><pre className="audit-detail">{JSON.stringify(JSON.parse(a.details),null,2)}</pre></details>)}</section>}
</section></main>{detail&&<div className="overlay"><section className="modal shared-modal"><div className="modal-top"><div><h2>{detail.titulo}</h2><p>Iniciada por <b>{detail.creatorName}</b> · {new Date(detail.createdAt).toLocaleString('pt-BR')} · revisão {detail.version}</p></div><button className="close" onClick={()=>setDetail(null)}>×</button></div><p>{message}</p><button disabled={busy} onClick={()=>open(detail.id)}>Recarregar ficha</button><h3>Colaboração</h3><label>Responsável<select disabled={busy||!can('Analisar editais')} value={detail.responsibleId||''} onChange={e=>update({responsibleId:e.target.value})}><option value="">Não atribuído</option>{team.map(t=><option key={t.id} value={t.id}>{t.nome}</option>)}</select></label><div>{team.map(t=><label key={t.id}><input type="checkbox" disabled={busy||!can('Analisar editais')} checked={(detail.collaborators||[]).includes(t.id)} onChange={e=>update({collaborators:e.target.checked?[...(detail.collaborators||[]),t.id]:(detail.collaborators||[]).filter(id=>id!==t.id)})}/>{t.nome}</label>)}</div><h3>Etapa e decisão</h3><select disabled={busy||!can('Registrar decisões')} value={detail.etapa} onChange={e=>update({etapa:Number(e.target.value)})}>{ETAPAS.map((s,i)=><option key={s} value={i}>{s}</option>)}</select><select disabled={busy||!can('Registrar decisões')} value={detail.decisao||''} onChange={e=>update({decisao:e.target.value})}><option value="">Sem decisão</option>{['Avaliar','Participar','Não participar'].map(s=><option key={s}>{s}</option>)}</select>
<ResumoItens key={detail.id} licitacao={detail} onSalvar={v=>update({itensPNCP:v})}/><h3>Documentos desta licitação</h3><p>PDFs até 20 MB. Arquivos vinculados exclusivamente a esta ficha.</p>{can('Acessar documentos')&&<input type="file" accept="application/pdf,.pdf" multiple disabled={busy} onChange={e=>{const files=Array.from(e.target.files);e.target.value='';run(async()=>{for(const f of files){const response=await fetch('/api/work/tenders/'+encodeURIComponent(detail.id)+'/documents',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/pdf','X-CSRF-Token':csrfToken,'X-File-Name':encodeURIComponent(f.name)},body:f});const out=await response.json();if(!response.ok)throw Error(out.error);}const d=await api('/api/work/tenders/'+encodeURIComponent(detail.id));setDetail(d);setMessage('PDFs gravados no servidor.');});}}/>}{(detail.documents||[]).map(d=><div className="doc-row" key={d.id}><label><input type="checkbox" checked={selectedDocs.includes(d.id)} onChange={e=>setSelectedDocs(v=>e.target.checked?[...v,d.id]:v.filter(x=>x!==d.id))}/>{d.name}</label><a href={'/api/work/tenders/'+encodeURIComponent(detail.id)+'/documents/'+d.id}>Baixar PDF</a><small>SHA-256: {d.hash.slice(0,16)}…</small></div>)}<button disabled={busy||!can('Analisar editais')||!selectedDocs.length} className="primary" onClick={()=>run(async()=>{const d=await api('/api/work/tenders/'+encodeURIComponent(detail.id)+'/summary','POST',{documentIds:selectedDocs});setDetail(d);await refresh();})}>{busy?'Processando…':'Gerar resumo dos PDFs selecionados'}</button><p>Até 4 PDFs por análise. Textos sem extração legível precisam passar por OCR antes. A chave da IA deve estar configurada no servidor.</p>
<AnalysisPanel key={detail.id+':'+(detail.summary?.generatedAt||'')} detail={detail} team={team} manual={manual} setManual={setManual} busy={busy} editable={can('Analisar editais')} onSave={async changes=>{await api('/api/work/tenders/'+encodeURIComponent(detail.id),'PATCH',{version:detail.version,changes});const d=await api('/api/work/tenders/'+encodeURIComponent(detail.id));setDetail(d);setManual(d.manual||{});await refresh();setMessage('Análise salva e registrada na auditoria.');}}/><h3>Documentos da proposta</h3><p>A seleção de PDFs acima também pode ser salva para preparação interna. Não envia proposta ao portal da licitação.</p><button disabled={busy||!can('Montar propostas')} onClick={()=>update({proposalDocuments:selectedDocs})}>Salvar seleção para proposta</button><h3>Comentários da equipe</h3>{(detail.comments||[]).map(c=><div className="notice" key={c.id}><b>{c.name}</b> · {new Date(c.created).toLocaleString('pt-BR')}<p>{c.text}</p></div>)}<textarea value={comment} onChange={e=>setComment(e.target.value)} maxLength={5000}/><button disabled={busy||!can('Analisar editais')||!comment.trim()} onClick={()=>run(async()=>{const d=await api('/api/work/tenders/'+encodeURIComponent(detail.id)+'/comments','POST',{text:comment});setDetail(d);setComment('');})}>Registrar comentário</button>{detail.urlOrigem&&<p><a href={detail.urlOrigem} target="_blank" rel="noreferrer">Abrir origem oficial ↗</a></p>}{detail.urlPNCP&&<p><a href={detail.urlPNCP} target="_blank" rel="noreferrer">Abrir PNCP ↗</a></p>}</section></div>}</div>;
}
